  "short": "商標法上の商標は「商品」に付けるトレードマークと「役務(サービス)」に付けるサービスマークに大別され、サービスマークは輸送業や金融業のようにサービスを提供する事業者が、自社の役務を他社の役務と区別するために使用する標章です。エの記述はまさにこの内容を表しています。イは商品につけるトレードマークの説明であり、アは企業そのものを識別する社標(コーポレートマーク的な概念)に近く、ウはプライベートブランド商品の商標という限定的な話であり、いずれもサービスマークの定義とは異なります。よって正解はエです。",
