  "short": "RFI(Request For Information、情報提供依頼書)は、新しいITソリューションの導入検討にあたり、その活用事例や技術情報などをベンダーに提供してもらうために発行する文書です。具体的な提案や見積りを求める前段階として、まず情報を集めて選択肢を把握する目的で用いられます。RFP(提案依頼書)は具体的なシステム要件を示して提案を求める文書であり、情報収集を目的とするRFIとは段階も目的も異なります。EDIは企業間の電子的なデータ交換の仕組み、KPIは重要業績評価指標であり、いずれも文書の種類とは無関係のため、正解はウです。",
