  "short": "RPA(Robotic Process Automation)は、これまで人が行っていたパソコン上の定型的な事務作業を、ソフトウェアのロボットに代替させることで業務の自動化・効率化を図る仕組みです。エの記述はこの内容そのものであり、RPAの定義として最も適切です。アは業務の一部を外部委託するアウトソーシング(BPO)の説明、イは工場で使われる産業用ロボット(ハードウェア)の説明、ウは利用者主体のシステム運用(EUC的な概念)の説明であり、いずれもソフトウェアロボットによる事務作業の自動化を指すRPAとは異なります。よって正解はエです。",
