  "field": "strategy",
  "category": "システム戦略",
  "q": "業務と情報システムを最適にすることを目的として，業務と情報システムの現状の把握と目標とする理想像の設定から現状と理想との乖離を明確にし，目標に向けた改善活動を移行計画として定義したい。このときに用いられる手法として，最も適切なものはどれか。",
  "choices": [
   "BI (Business Intelligence)",
   "EA (Enterprise Architecture)",
   "MOT (Management of Technology)",
   "SOA (Service Oriented Architecture)"
  ],
  "answer": 1,
  "hint": "",
  "short": "EA(Enterprise Architecture)は、企業全体の業務プロセスと情報システムを最適化することを目的に、現状(As-Is)の把握と目指すべき理想像(To-Be)を設定し、両者のギャップを埋めるための移行計画を策定する手法です。設問にある「現状把握と理想像の設定から乖離を明確にし、移行計画を定義する」という一連の流れは、まさにEAの標準的な進め方に対応します。BIはデータを分析・活用して経営判断を支援する仕組み、MOTは技術を経営に活かすマネジメント手法、SOAはサービス単位でシステムを構築するアーキテクチャスタイルであり、いずれも業務と情報システム全体の最適化計画を策定する手法としては該当しません。よって正解はイです。",
  "whyWrong": null,
