  "short": "アジャイルモデルは、あらかじめ要件を全て確定してから開発を進めるウォーターフォールモデルが抱える「変更への対応の弱さ」という課題を改善する形で提唱された開発手法の総称です。短い開発サイクル(イテレーション)を繰り返すことで、開発途中で生じる仕様変更や優先順位の変化に迅速に対応できる点が最大の特徴です。したがって空欄aには「課題を改善」、空欄bには「開発工程で生じる種々の変更に迅速に対応」が入ります。「開発工程を順に実施」はむしろウォーターフォールモデルの特徴であり、アジャイルの目的とは逆であるため不適切です。よって正解はアです。",
