  "short": "変更管理委員会は、変更要求がプロジェクトのコスト・スケジュール・品質などに与える影響を総合的に審議し、承認・却下を判断する権限を持っています。イの記述にあるように、コストの増加や期日の延期といった影響が大きいと判断された場合には、変更要求を却下することも委員会の正当な役割です。アは第三者ではなくプロジェクトのステークホルダを含めて審議されるべき点で誤り、ウはスコープ変更を伴う要求も審議対象となり得るため無条件の限定は誤り、エは全ての変更要求が必ずPMの事前承認を経るとは限らないため誤りです。よって正解はイです。",
