  "hint": "",
  "short": "ISMSの内部監査では、JIS Q 27001が要求する事項や組織自らが定めた要求事項への適合性を確認するだけでなく、実際にISMSの活動が組織にとって有効に機能しているかどうかという有効性の観点からも評価を行う必要があります。アの記述はこの両面の評価を的確に表しています。イは組織独自の基準のみを監査基準とするとしていますが、JIS Q 27001の要求事項も監査基準に含める必要があるため誤りです。ウは前回の監査結果を考慮しないとしていますが、実際には内部監査プログラムの計画時に過去の結果を踏まえるべきであり誤りです。エは内部監査を不定期・抜き打ちで行うことを原則としていますが、実際には計画的・定期的に実施することが原則であるため誤りです。よって正解はアです。",
