  "q": "バイオメトリクス認証の他人受入率と本人拒否率に関する次の記述中のa，bに入れる字句の適切な組合せはどれか。 バイオメトリクス認証の認証精度において，他人受入率を低く抑えようとすると[a]が高くなり，本人拒否率を低く抑えようとすると[b]が高くなる。\n\n| | a | b |\n|---|---|---|\n| ア | 安全性 | 可用性 |\n| イ | 安全性 | 利便性 |\n| ウ | 利便性 | 安全性 |\n| エ | 利便性 | 可用性 |",
