  "field": "technology",
  "category": "セキュリティ",
  "q": "Webサービスを狙った攻撃に関する記述と攻撃の名称の適切な組合せはどれか。 a Webサービスが利用しているソフトウェアに脆弱性の存在が判明したとき，その修正プログラムが提供される前に，この脆弱性を突いて攻撃する。 b 複数のコンピュータから大量のパケットを一斉に送り付けることによって，Webサービスを正常に提供できなくさせる。 c 理論的にあり得るパスワードのパターンを順次試すことによって，正しいパスワードを見つけ，攻撃対象のWebサービスに侵入する。\n\n| | a | b | c |\n|---|---|---|---|\n| ア | DDoS攻撃 | ゼロデイ攻撃 | ブルートフォース攻撃 |\n| イ | DDoS攻撃 | ブルートフォース攻撃 | ゼロデイ攻撃 |\n| ウ | ゼロデイ攻撃 | DDoS攻撃 | ブルートフォース攻撃 |\n| エ | ゼロデイ攻撃 | ブルートフォース攻撃 | DDoS攻撃 |",
  "choices": [
   "a: DDoS攻撃, b: ゼロデイ攻撃, c: ブルートフォース攻撃",
   "a: DDoS攻撃, b: ブルートフォース攻撃, c: ゼロデイ攻撃",
   "a: ゼロデイ攻撃, b: DDoS攻撃, c: ブルートフォース攻撃",
   "a: ゼロデイ攻撃, b: ブルートフォース攻撃, c: DDoS攻撃"
  ],
  "answer": 2,
  "hint": "",
  "short": "ゼロデイ攻撃は、脆弱性の修正プログラム(パッチ)が提供される前にその脆弱性を突いて行われる攻撃であり、aの記述に対応します。DDoS攻撃は複数のコンピュータから大量のパケットを同時に送りつけてサービスを妨害する攻撃であり、bの記述に対応します。ブルートフォース攻撃(総当たり攻撃)は、あり得るパスワードの組合せを機械的に順次試して不正ログインを試みる攻撃であり、cの記述に対応します。したがってa=ゼロデイ攻撃、b=DDoS攻撃、c=ブルートフォース攻撃となり、正解はウです。",
  "whyWrong": null,
