  "field": "technology",
  "category": "アルゴリズムとプログラミング",
  "q": "手続calcMod3を呼び出したときの出力はどれか。\n\n〔プログラム〕\n○calcMod3()\n　整数型: totalValue, i\n　totalValue ← 0\n　for (iを1から7まで1ずつ増やす)\n　　if (i ÷ 3の余り が 0と等しい)\n　　　totalValue ← totalValue + i\n　　endif\n　endfor\n　totalValueを出力する",
