  "hint": "",
  "short": "CRL(Certificate Revocation List、証明書失効リスト)は、まだ有効期間内であるにもかかわらず、鍵の漏えいなどの理由により失効させられたデジタル証明書の一覧を公開したものです。ウの記述はこの定義に正確に対応しています。有効期間が単に満了しただけの証明書は自然に無効となるためCRLに掲載する必要はなく、有効期間が無期限であることや延長されていることはCRLへの掲載条件とは無関係です。よって正解はウです。",
