  "category": "セキュリティ",
  "q": "Aさんは，Bさんから次の4種類のメッセージを受け取った。Aさんが，受け取ったメッセージを復号して読むことができるものだけを全て挙げたものはどれか。 a AさんとBさんとの共通鍵で暗号化したメッセージ b Aさんの公開鍵で暗号化したメッセージ c Bさんの公開鍵で暗号化したメッセージ d Bさんの秘密鍵で暗号化したメッセージ",
