  "short": "共通鍵暗号方式では、AさんとBさんが共有する共通鍵(a)で暗号化されたメッセージは、その共通鍵を持つAさん自身が復号できます。公開鍵暗号方式では、暗号化に使った公開鍵の対となる秘密鍵を持つ人だけが復号できるため、Aさんの公開鍵で暗号化されたメッセージ(b)はAさんの秘密鍵で復号可能であり、Bさんの秘密鍵で暗号化されたメッセージ(d、いわゆる署名的な用途)はBさんの公開鍵で誰でも検証・復号できます。一方、Bさんの公開鍵で暗号化されたメッセージ(c)は、対になるBさんの秘密鍵を持つBさんしか復号できず、Aさんは復号できません。したがって復号できるのはa、b、dであり、正解はアです。",
