  "category": "コンピュータシステム",
  "q": "稼働率0.9の装置で並列システムを構成したい。このシステムの稼働率を0.999とするためには，最低何台の装置で並列システムを構成する必要があるか。ここで，並列システムを構成したときに，少なくとも1台の装置が稼働していればシステムは正常に稼働しているものとする。",
  "choices": [
   "2",
   "3",
   "4",
   "5"
  ],
  "answer": 1,
  "hint": "",
  "short": "並列システムの稼働率は、少なくとも1台が稼働していればよいため「1-(全台故障の確率)」で計算でき、稼働率0.9(故障率0.1)の装置をn台並列にした場合、システム稼働率は1-(0.1)^nとなります。n=2の場合は1-0.01=0.99で目標の0.999に届きませんが、n=3の場合は1-0.001=0.999となり、目標の稼働率0.999をちょうど満たします。したがって必要な最低台数は3台であり、正解はイです。",
