  "hint": "",
  "short": "BYOD（Bring Your Own Device）とは，従業員が個人で所有するスマートフォンやノートPCなどの携帯情報端末を，企業が許可した上で業務に利用させる仕組みを指す用語である。選択肢アはまさにこの定義どおりの内容であり，正解となる。イはRPAによる定型業務の自動化，ウは業務プロセスの継続的改善（カイゼン），エは抜本的な業務改革（BPR）の説明であり，いずれもBYODとは異なる別の経営・IT用語の説明になっている。",
