  "short": "パブリシティ権とは，著名人の氏名や肖像などが持つ顧客吸引力を，本人が独占的に利用できる権利であり，芸能人やスポーツ選手の写真を無断で商業利用する行為はこの権利の侵害となり得る。設問では，人気選手の写真を撮影・プリントして販売しており，選手の知名度や人気を利用した商業行為であるため，パブリシティ権の侵害が問題となる。意匠権（ア）は物品のデザイン，商標権（イ）は商品・サービスを識別する標章，著作権（ウ）は写真自体の創作性に関する権利であり，写真を撮った側にこそ生じ得る権利であるため，選手側の権利としては適切でない。",
  "whyWrong": null,
  "society": "",
  "memo": "",
  "source": "令和8年度 ITパスポート試験 公開問題 問11（IPA）",
