  "hint": "",
  "short": "匿名加工情報とは，個人情報保護法で定められた，特定の個人を識別できないように，かつ元の個人情報に復元できないように加工した情報であり，一定の基準を満たせば本人の同意を得ずに事業者間で利活用することが認められている。選択肢ウはこの復元不可能性と本人同意なしの利活用という二つの要件を正しく説明している。イは「復元を担保した」としており，復元できないことが要件である匿名加工情報の定義と矛盾するため誤りであり，アは単なる統計情報の加工・ひも付けの説明であって匿名加工情報の制度とは異なる。",
