  "field": "strategy",
  "category": "ビジネスインダストリ",
  "q": "AIを利活用する上で留意すべき事項として，適切なものだけを全て挙げたものはどれか。 a AIの意図しない動作によって，人間の生命や身体などに危害を及ぼす可能性 b AIの判断に差別的な内容が含まれる可能性 c AIの判断にプライバシーの侵害となる内容が含まれる可能性",
