  "field": "strategy",
  "category": "ビジネスインダストリ",
  "q": "大容量，頻繁な更新，多種多様という三つの要素をもつ情報資産を\"ビッグデータ\"と定義する考え方がある。このビッグデータを特徴づける三つの要素を総称して何というか。",
  "choices": [
   "3C",
   "3D",
   "3G",
   "3V"
  ],
  "answer": 3,
  "hint": "",
  "short": "ビッグデータは，データ量が大きいこと（Volume），更新頻度が高くリアルタイム性があること（Velocity），データの種類が多様であること（Variety）という三つの特徴で特徴づけられることが多く，これらの頭文字を取って3Vと呼ばれる。したがって正解はエであり，3C（ア）はマーケティング分析（Customer, Competitor, Company）などの枠組み，3D・3Gは全く異なる分野の用語であって，ビッグデータの三要素を表す総称ではない。",
  "whyWrong": null,
  "society": "",
