  "answer": 2,
  "hint": "",
  "short": "請負契約は，請負人が仕事を完成させ，その成果物を注文者に引き渡すことによって，注文者に報酬支払義務が生じるという「仕事の完成」に対して対価が支払われる契約類型である。特段の取決めがない場合，民法の原則に従えば，プログラムの引渡しをもって報酬支払義務が発生するため，選択肢ウが適切である。エのように注文者が完成前にいつでも無償で契約解除できるわけではなく（請負人に損害が生じれば賠償が必要），アの再委託（下請け）についても原則として自由に行える場合が多く，イの欠陥修改請求も無制限にいつでも認められるわけではないため，いずれも不適切である。",
