  "short": "IT基本計画の策定にあたっては，どのようなステークホルダがITシステムの利活用に関わるか（a），組織の現在および将来のニーズにどう対応するか（b）を明確にすることが求められる。一方，cのインシデント管理手順やdの業務要件・優先順位の詳細な合意事項は，IT基本計画そのものよりも下位のより具体的な運用計画やプロジェクト計画の段階で定めるべき内容である。したがって，IT基本計画の策定段階で明確にすべき事項はaとbであり，正解はアとなる。",
