  "field": "management",
  "category": "プロジェクトマネジメント",
  "q": "クライアントPCへのソフトウェアの導入作業が契約に含まれるシステム開発プロジェクトがある。導入作業の行動に関する記述のうち，適切なものだけを全て挙げたものはどれか。 a 導入作業中に契約外のPCが見つかった。そのPCを導入対象外とした。 b 導入作業中に契約外のPCへの導入を依頼された。依頼に基づいて，その対応を無償で行った。 c 導入作業の続行が困難な状態となった。発注者と合意し，導入前の状態に復旧した。",
  "choices": [
   "a",
   "a, b",
   "a, c",
   "b, c"
  ],
  "answer": 2,
  "hint": "",
  "short": "システム開発プロジェクトにおいて，契約で定められた作業範囲（スコープ）を逸脱する作業は，たとえ依頼されても勝手に実施すべきではなく，契約変更などの正式な手続きを経る必要がある。aは契約外のPCを対象外として扱っており適切，cは続行困難になった際に発注者と合意のうえで原状回復しており適切な対応である。一方bは契約外のPCへの対応を，発注者との取決めなしに無償で行ってしまっており，スコープ管理の観点から不適切である。したがって適切なものはaとcであり，正解はウとなる。",
