  "answer": 3,
  "hint": "",
  "short": "プロジェクトの計画段階で詳細な情報がまだ少ない初期の段階では，過去に実施した類似プロジェクトの実績データを参考にして概算のコストを見積もる類推見積りの手法が適しており，短期間で大まかな費用感をつかむことができる。FP法（ア）や作業単位の積み上げ（イ），コード行数からの見積り（ウ）は，いずれも機能や作業の詳細な分解が必要な，より詳細な見積り技法であり，計画段階の初期に短期的な概算を得る手法としては手間がかかりすぎるため適切ではない。",
  "whyWrong": null,
  "society": "",
  "memo": "",
