  "short": "機能や不具合修正の候補を一覧で管理し，優先順位をつけながら短い期間（この場合2週間）ごとに繰り返しリリースを行う進め方は，反復的かつインクリメンタルに開発を進めるアジャイル開発の典型的な特徴である。ウォーターフォール（ウ）は工程を一度きり順番に進める開発モデルであり，短いサイクルでの繰り返しリリースには向かない。DevOps（ア）は開発と運用の連携を強化する文化・手法であり開発モデルそのものではなく，リバースエンジニアリング（エ）は既存のソフトウェアを解析して仕様を導き出す技術であるため，いずれも設問の状況を表す開発モデルとしては適切でない。",
