  "hint": "",
  "short": "サービスレベル管理は，SLA（サービスレベル合意書）の計画立案からサービス内容の交渉，草案作成，合意，導入，そして実際のサービス提供状況の測定・評価に至るまでの一連の活動を継続的に行うITサービスマネジメントのプロセスである。したがって正解はイである。サービスレベル契約（ウ）はSLAという合意文書そのものを指す言葉であり，活動（プロセス）ではなく成果物であるため，設問が問う一連の活動を表す用語としては適切でない。アウトソーシング（ア）は業務の外部委託，リエンジニアリング（エ）は業務プロセスの抜本的な再設計を指す別の概念である。",
