  "hint": "",
  "short": "電子メールをサーバへ送信する際にはSMTP（Simple Mail Transfer Protocol）が使われ，サーバから自分のメールボックスの内容を受信する際にはPOP3やIMAP4が使われる。設問の組合せのうち，送信にSMTP，受信にIMAP4を用いる組合せはこの一般的な役割分担と合致しており，正解はエとなる。他の選択肢は送信・受信のいずれかにSMTP以外を送信プロトコルとして割り当てていたり，受信プロトコルにSMTPを割り当てていたりしており，実際のメールプロトコルの役割とは矛盾している。",
