  "field": "technology",
  "category": "AI",
  "q": "ある推論システムは，演繹推論，帰納推論，仮説形成などの推論が実行できる。この推論システムへの入力と得られた出力に関する記述のうち，演繹推論を実行した例として，適切なものはどれか。",
  "choices": [
   "\"HDDとSSDは記憶装置である\"と入力した後に，\"HDDの台数を増やすと記憶容量が増える\"と入力した。出力は，\"SSDの台数を増やすと記憶容量が増える\"となった。",
   "\"HDDは台数を増やすと記憶容量が増える\"と入力した後に，\"記憶装置は台数を増やすと記憶容量が増える\"と入力した。出力は，\"HDDは記憶装置である\"となった。",
   "\"記憶装置であるHDDは記憶容量をもつ\"と入力し，同時に\"記憶装置であるSSDは記憶容量をもつ\"と入力した。出力は，\"全ての記憶装置は記憶容量をもつ\"となった。",
   "\"全ての記憶装置は記憶容量をもつ\"と入力した後に，\"HDDは記憶装置である\"と入力した。出力は，\"HDDは記憶容量をもつ\"となった。"
  ],
  "answer": 3,
  "hint": "",
  "short": "演繹推論は，「すべての記憶装置は記憶容量をもつ」という一般的・普遍的な前提と，「HDDは記憶装置である」という個別の事実から，論理的に「HDDは記憶容量をもつ」という結論を導き出す推論方法であり，いわゆる三段論法に相当する。選択肢エはこの構造そのものであり正解となる。ア・ウは個別の事例から一般的な規則を導き出す帰納推論，イは観察された事実から説明となる仮説を導き出す仮説形成（アブダクション）の例であり，一般法則から個別の結論を導く演繹推論とは推論の方向性が異なる。",
