  "short": "NAS（Network Attached Storage）は，ネットワークに直接接続して使用し，複数のPCやスマートフォンなどからネットワーク経由でアクセスできる外部記憶装置であり，設問の説明に合致する。ランダムアクセスによるファイル形式（イ）やRAIDのような複数記憶装置の分散管理技術（ウ），無線LANの識別文字列であるSSID（エ）は，いずれもNASとは異なる別の技術・概念の説明であるため，正解はアとなる。",
